"""Build a static, explicitly offline report from actual deterministic helper outputs."""
from pathlib import Path
import argparse,html,json,shutil

ROOT=Path(__file__).resolve().parents[1]
def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--demo',required=True,type=Path);parser.add_argument('--output',required=True,type=Path)
    args=parser.parse_args();demo=args.demo.resolve();out=args.output.resolve();out.mkdir(parents=True,exist_ok=True)
    summary=json.loads((demo/'validation.json').read_text(encoding='utf-8'));styles=json.loads((demo/'matched-styles.json').read_text(encoding='utf-8'))['selected']
    assert summary['synthetic']and not summary['image_model_or_service_called']
    for name in ['synthetic-input.png','synthetic-export.png','validation.json','matched-styles.json','prompt-packages.json','qa-uncertain-result.json','qa-limit-result.json','export-report.json']:
        shutil.copyfile(demo/name,out/name)
    source=ROOT/'docs/workflow.svg'
    if source.resolve()!=(out/'workflow.svg').resolve():shutil.copyfile(source,out/'workflow.svg')
    cards=''.join('<article><div class="family">'+html.escape(s['family'])+'</div><h3>'+html.escape(s['name_zh'])+'</h3><p>'+html.escape(s['philosophy'])+'</p><p class="meta">标签匹配分 '+str(s['score'])+' · '+html.escape(s['reason'])+'</p></article>'for s in styles)
    page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Super Image Art Director · 离线演示</title><style>*{box-sizing:border-box}body{margin:0;background:#082a38;color:#eff8ed;font:16px/1.7 system-ui,sans-serif}main{max-width:1140px;margin:auto;padding:clamp(18px,4vw,48px)}.eyebrow,.family{color:#79dab7;letter-spacing:.08em;font-size:13px}h1{font-size:clamp(28px,5vw,52px);line-height:1.17}h2{margin-top:42px}.notice{padding:18px 22px;border-left:4px solid #edbf74;background:#183d4b;color:#f4dcae}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:18px}.cards article,.figure{padding:20px;background:#123a49;border:1px solid #2a5661;border-radius:14px}.meta{font-size:14px;color:#bddbd0}a{color:#8ee2bd}img{display:block;width:100%;max-width:100%;object-fit:contain}.diagram{background:#082a38}figure{margin:0}figcaption{padding-top:12px;color:#c5dcd2}.exports{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(290px,100%),1fr));gap:18px}.exports img{height:380px}.stats{display:flex;flex-wrap:wrap;gap:16px;margin:28px 0}.stat{background:#155269;padding:12px 20px;border-radius:12px}.stat b{display:block;font-size:28px}.links{display:flex;gap:16px;flex-wrap:wrap}</style></head><body><main><header><div class="eyebrow">AGENT SKILL / DETERMINISTIC OFFLINE HELPERS</div><h1>把视觉需求，整理成<br>可追溯的创意流程。</h1><p class="notice">离线实际运行演示：合成 brief、标签检索、提示词、模拟 QA 与几何 PNG 导出。本次未调用图像模型、未上传参考图；页面没有 AI 生成的海报或真实视觉质量通过记录。</p><div class="stats"><div class="stat"><b>53</b>风格卡</div><div class="stat"><b>3</b>不同风格族</div><div class="stat"><b>480 × 640</b>实际导出像素</div></div><div class="links"><a href="validation.json">运行记录</a><a href="prompt-packages.json">3 份实际提示词</a><a href="matched-styles.json">检索结果</a></div></header><h2>流程示意</h2><p>实线为可离线运行的脚本环节，虚线为此次未验证的宿主图像工具与视觉审查。</p><img class="diagram" src="workflow.svg" alt="明确标示的流程示意图，不是模型成图"><h2>这份合成 brief 的实际推荐</h2><p class="meta">分数来自原脚本的标签权重，表示输入匹配情况，不表示成图质量。</p><section class="cards">'''+cards+'''</section><h2>原导出器的真实几何测试</h2><section class="exports"><figure class="figure"><img src="synthetic-input.png" alt="新造的320乘180几何像素"><figcaption>输入：320 × 180，代码新造几何像素。</figcaption></figure><figure class="figure"><img src="synthetic-export.png" alt="实际480乘640等比补边结果"><figcaption>输出：480 × 640，等比适配，上下各补边185像素。未经批准的裁切与覆盖输入均被拒绝。</figcaption></figure></section><h2>模拟 QA：保持未通过</h2><p>没有真实生成图时，示例记录保留不确定状态，实际状态机返回 regenerate；第二次修正上限返回 failed_preview。它没有执行视觉检测。</p><div class="links"><a href="qa-uncertain-result.json">不确定记录的结果</a><a href="qa-limit-result.json">修正上限的结果</a><a href="export-report.json">导出元数据</a></div><p class="meta">实际模型质量、宿主端到端执行和私人参考图处理均未验证。所有示例输入均为新造合成数据；品牌图库原图、Logo、模型和个人配置不在本演示中。</p></main></body></html>'''
    (out/'index.html').write_text(page,encoding='utf-8')
    print(json.dumps({'static_preview_built':True,'image_model_called':False,'style_cards':len(styles),'local_images':3}))
if __name__=='__main__':main()
